+package org.apache.streampipes.commons.network;
+
+import java.net.InetAddress;
+import java.net.MalformedURLException;
+import java.net.URL;
+import java.net.UnknownHostException;
+
+public class NetworkingUtils {
+
+  /**
+   * Validates that a URL is safe to fetch from server-side.
+   * Prevents SSRF by blocking non-HTTP(S) protocols and internal IP addresses.
+   */
+  public static void validateUrl(String urlString) {
+    try {
+      URL url = new URL(urlString);
+      String protocol = url.getProtocol().toLowerCase();
+      
+      if (!"http".equals(protocol) && !"https".equals(protocol)) {
+        throw new IllegalArgumentException("Only HTTP and HTTPS protocols are allowed");
+      }
+      
+      // Resolve hostname to prevent DNS rebinding attacks
+      InetAddress address = InetAddress.getByName(url.getHost());
+      if (isInternalAddress(address)) {
+        throw new IllegalArgumentException("Internal IP addresses are not allowed");
+      }
+    } catch (MalformedURLException | UnknownHostException e) {
+      throw new IllegalArgumentException("Invalid URL provided", e);
+    }
+  }
+  
+  private static boolean isInternalAddress(InetAddress address) {
+    return address.isLoopbackAddress() || 
+           address.isSiteLocalAddress() || 
+           address.isAnyLocalAddress() ||
+           address.isLinkLocalAddress();
+  }
+}
