+        maxFunctionLocals: UInt32 = 50000,
+        maxBrTableTargets: UInt32 = 10000000,
+        maxCallStackDepth: Int = 1000,
+        maxMemoryPages: UInt32 = 65536, // 4GB
+        maxExecutionFuel: UInt64? = nil
