+        self.maxModuleSize = maxModuleSize
+        self.maxFunctionLocals = maxFunctionLocals
+        self.maxBrTableTargets = maxBrTableTargets
+        self.maxCallStackDepth = maxCallStackDepth
+        self.maxMemoryPages = maxMemoryPages
+        self.maxExecutionFuel = maxExecutionFuel
+    }
+    
+    public static let `default` = ResourceLimits()
+    
+    public static let strict = ResourceLimits(
+        maxModuleSize: 10 * 1024 * 1024, // 10MB
+        maxFunctionLocals: 5000,
+        maxBrTableTargets: 100000,
+        maxCallStackDepth: 100,
+        maxExecutionFuel: 10000000
+    )
